export default function ({ page, response, previous }) {
  const p = previous?.pageId === page.pageId ? previous : { pageId: page.pageId, blocks: [] };
  if (!Array.isArray(response.results)) throw Error("Notion response missing blocks");
  const blocks = [...p.blocks, ...response.results];
  if (response.has_more && !response.next_cursor) throw Error("Notion cursor missing");
  return {
    state: { pageId: page.pageId, blocks },
    more: response.has_more,
    cursor: response.next_cursor ?? null,
  };
}

