export default function ({ state, page }) {
  const text = state.blocks
    .filter((b) => !["image", "video"].includes(b.type))
    .map((b) =>
      ["child_page", "child_database"].includes(b.type)
        ? (b[b.type]?.title ?? "")
        : (b[b.type]?.rich_text ?? []).map((x) => x.plain_text ?? x.text?.content ?? "").join(""),
    )
    .filter(Boolean)
    .join("\n");
  const chars = Array.from(text),
    chunks = [];
  for (let i = 0; i < chars.length; i += 800) {
    const c = chars.slice(i, i + 920).join("");
    if (c) chunks.push(c);
  }
  return { chunks, page };
}

