export default async function ({ page, index }, ctx) {
  const key = `notion:${page.pageId}:${index}`,
    v = await ctx.state.get(key);
  if (v?.status === "pending") throw Error("Inspect Supabase before retry");
  if (v?.status === "done") return { key, skip: true };
  await ctx.state.set(key, { status: "pending" });
  return { key, skip: false };
}

