export default function ({ embedding, page, text, index }) {
  const v = embedding?.data?.[0]?.embedding;
  if (!Array.isArray(v) || v.length !== 1536 || v.some((x) => !Number.isFinite(x)))
    throw Error("Invalid embedding");
  return {
    body: {
      content: text,
      metadata: {
        pageId: page.pageId,
        createdTime: page.createdTime,
        pageTitle: page.title,
        chunk: index,
      },
      embedding: v,
    },
  };
}

