export default async function ({ key, body }, ctx) {
  if (!Array.isArray(body) || body.length !== 1 || !body[0].id)
    throw Error("Unknown Supabase insert outcome");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}
